-- N2 grammar meanings + enrichment — batch 3 (bunpo_N2.pdf trang 41-60)
-- Nguồn: 完全マスター 日本語能力試験2級 文法 (mục 85-137, 53 điểm ngữ pháp).
-- Đối chiếu 53 mục với n2_grammar_id_title.tsv: TẤT CẢ đều khớp chính xác,
-- không có mục nào ghi "KHÔNG KHỚP".
-- Đã kiểm tra chéo với seed_n2_grammar_meanings_batch1/2/4.sql (grep "where id = '...'")
-- để loại trùng: không có id nào trong 53 id dưới đây trùng với 3 batch kia.
-- (Mục 138 ～つつ／～つつも đến 141 ～どころか nằm ở đầu trang 61-62, đã được
-- batch4 xử lý — không lặp lại ở đây.)

-- ============ grammar_meanings ============

-- 85 ～くせに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('a42e83c5-1b8c-551a-9e00-65c1a3b54d23', 0, 'Dù, mặc dù — nhấn mạnh sắc thái khinh miệt, chê trách với điều nói ở vế sau.', ARRAY['よく知らないくせに、あの人は何でも説明したがる。','彼は、若いくせにすぐ疲れたと言う。']::text[], ARRAY['Dù chả biết mấy nhưng ông kia cái gì cũng muốn giải thích.','Anh ấy dù còn trẻ nhưng hơi tí là kêu mệt.']::text[]);

-- 86 ～ことから
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d9c79c98-8177-5019-8af1-13df14f67502', 0, 'Vì, bởi vì — nêu một sự việc/hiện tượng quan sát được làm căn cứ để suy ra kết luận ở vế sau.', ARRAY['道がぬれていることから、昨夜、雨が降ったことがわかった。','二人が一緒に仕事をしたことから、交際が始まった。']::text[], ARRAY['Vì đường bị ướt nên biết là đêm qua trời đã mưa.','Vì đã cùng làm việc với nhau nên hai người bắt đầu quen nhau.']::text[]);

-- 87 ～ことに（は）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('67c058b5-f614-5748-8785-335198fc0a61', 0, 'Đặt trước câu để nhấn mạnh cảm xúc, tâm trạng của người nói (thật đáng ~ là...).', ARRAY['驚いたことに、私の祖父と恋人のおじいさんは小学校時代の友達だったそうだ。','ありがたいことに、奨学金がもらえることになった。']::text[], ARRAY['Đáng ngạc nhiên là, nghe nói ông tôi và ông của người yêu lại là bạn học hồi tiểu học.','Thật may mắn là tôi đã nhận được học bổng.']::text[]);

-- 88 ～上（は）／～上も／～上の
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('1c9fbc04-eceb-5c40-86a5-6ff11df13ed5', 0, 'Xét từ góc độ, phương diện ~ (lịch sử, pháp luật, lý thuyết...).', ARRAY['京都には歴史上有名なお寺が数多くある。','これは理論上は可能だが、実用化には時間がかかりそうだ。']::text[], ARRAY['Kyoto có rất nhiều ngôi chùa nổi tiếng xét về mặt lịch sử.','Cái này về lý thuyết thì có thể, nhưng để đưa vào thực tế thì có vẻ tốn thời gian.']::text[]);

-- 89 ～た末（に）／～た末の／～の末（に）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('0bdd119f-70b9-5011-8e5c-769cac70abee', 0, 'Sau một quá trình dài làm/trải qua việc gì đó (cuối cùng thì...).', ARRAY['いろいろ考えた末、会社を辞めることにした。','苦労した末の成功は、何よりもうれしいものだ。']::text[], ARRAY['Sau khi suy nghĩ rất nhiều, tôi đã quyết định nghỉ việc.','Thành công sau bao gian khó thì hạnh phúc hơn bất cứ điều gì.']::text[]);

-- 90 ～たところ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('8f5a53ef-c933-5d66-9ede-2a00dec9377e', 0, 'Sau khi làm ~ thì phát hiện/xảy ra kết quả này (kể lại một khám phá bất ngờ).', ARRAY['新しいワープロを使ってみたところ、とても使いやすかった。','コンピューターが動かず、どうしていいか困っていたところ、山田さんが助けてくれた。']::text[], ARRAY['Thử dùng máy đánh chữ mới thì thấy rất dễ dùng.','Máy tính không chạy, đang khốn khổ không biết làm sao thì được anh Yamada giúp đỡ.']::text[]);

-- 91 ～ついでに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('da25d60c-c1c4-559b-a1c2-522b362cab91', 0, 'Nhân tiện, tiện thể làm luôn việc khác trong lúc đang làm một việc.', ARRAY['銀行へ行くついでにこの手紙を出してくれませんか。','デパートへ買い物に行ったついでに、着物の展示会を見て来た。']::text[], ARRAY['Tiện thể đi ngân hàng, anh gửi giúp em lá thư này được không?','Tiện thể đi mua sắm ở trung tâm thương mại, tôi đã ghé xem triển lãm kimono.']::text[]);

-- 92 ～というと／～といえば
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3040e16c-734e-5a29-ad1c-4d5490083ddb', 0, 'Nhắc đến chủ đề đó thì liên tưởng ngay đến ví dụ tiêu biểu nhất.', ARRAY['スポーツの祭典というと、まずオリンピックですね。','古典芸能といえば、何といっても歌舞伎でしょう。']::text[], ARRAY['Nói đến ngày hội thể thao thì trước hết phải là Olympic nhỉ.','Nói về nghệ thuật cổ điển thì dù sao cũng phải là Kabuki.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3040e16c-734e-5a29-ad1c-4d5490083ddb', 1, 'Từ chủ đề đang nói mà nhớ ra, liên tưởng đến một việc khác.', ARRAY['昨日、ジョンさんに会いましたよ。ジョンさんといえばA社に就職が決まったそうですね。','イタリアといえば、パスポートを落として困ったことを思い出します。']::text[], ARRAY['Hôm qua tớ gặp anh John đấy. Nhắc đến anh John, nghe nói anh ấy đã được nhận vào làm ở công ty A.','Nhắc đến Italia, lại nhớ đến lần khốn khổ vì làm mất hộ chiếu.']::text[]);

-- 93 ～といったら
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('23d271c5-1079-5eba-9172-47540aa60bea', 0, 'Diễn tả cảm thán, ngạc nhiên hoặc thất vọng về mức độ của điều được nhắc tới (cả tích cực lẫn tiêu cực).', ARRAY['息子の部屋の汚いことといったら、ひどいものです。','その景色の美しさといったら、口で言い表せないほどです。']::text[], ARRAY['Nói về độ bẩn của phòng con trai tôi thì kinh khủng lắm.','Vẻ đẹp của phong cảnh đó thì không lời nào tả xiết.']::text[]);

-- 94 ～というより
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7aba60a4-1e30-56cb-84b3-8ff2770dc4c8', 0, 'Nói là ~ nhưng thực ra dùng từ/cách diễn đạt khác thì đúng hơn (đính chính lại cách nói).', ARRAY['彼の言い方は勧めているというより、強制しているようだ。','冷房がききすぎて、涼しいというより寒い。']::text[], ARRAY['Cách nói của anh ta có vẻ không phải là khuyên nhủ mà là ép buộc thì đúng hơn.','Điều hòa mạnh quá, nói là mát thì không đúng bằng nói là lạnh.']::text[]);

-- 95 ～ば～ほど
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('f8efbc69-a93b-5167-aa1c-8eefb58ec8ba', 0, 'Càng ~ thì càng ~ (mức độ vế trước tăng lên kéo theo mức độ vế sau cũng tăng theo).', ARRAY['練習すればするほど上手になります。','給料は高ければ高いほどいいですね。']::text[], ARRAY['Càng luyện tập càng giỏi lên.','Lương càng cao thì càng tốt nhỉ.']::text[]);

-- 96 ～ほど
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('51643c2b-e39f-569a-bf44-59fd6b1b2c98', 0, 'Mức độ của một vế thay đổi thì mức độ vế còn lại cũng thay đổi theo (một mình ほど, không cần ば).', ARRAY['相撲では、太っているほど有利だ。','値段が高いほど品物がいいとは限らない。']::text[], ARRAY['Trong Sumo, càng béo thì càng có lợi.','Không hẳn cứ giá cao thì hàng tốt.']::text[]);

-- 97 ～かのようだ／～かのような／～かのように
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('2048a890-2bd9-57ca-ba42-bccc0bd9072a', 0, 'Thực tế không phải vậy nhưng có vẻ/cứ như là ~.', ARRAY['激しい雨と風は、まるで台風が来たかのようだ。','彼はそのことについては、何も知らないかのような顔をしている。']::text[], ARRAY['Mưa gió dữ dội như thể bão đã đổ bộ vậy.','Về việc đó, anh ta tỏ ra mặt như thể chẳng biết gì.']::text[]);

-- 98 ～つつある
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('43c4dc99-b104-5bb9-9b14-893e801c6329', 0, 'Đang dần dần ~ (một sự thay đổi đang diễn ra theo từng bước), thường dùng trong văn viết.', ARRAY['景気は徐々に回復しつつある。','問題は改善されつつあるが、時間がかかりそうだ。']::text[], ARRAY['Tình hình kinh tế đang dần dần phục hồi.','Vấn đề đang dần được cải thiện, nhưng có vẻ còn tốn thời gian.']::text[]);

-- 99 ～てたまらない／～てしようがない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('a6d6b6ca-b76e-5e42-8987-7e7c6bc3db60', 0, 'Cảm xúc/cảm giác mạnh đến mức không thể kìm nén được, chủ ngữ giới hạn ở ngôi thứ nhất.', ARRAY['頭痛がしてたまらないので、近くの病院に行った。','ビデオカメラが欲しくてしようがない。']::text[], ARRAY['Vì đau đầu không chịu nổi nên tôi đã đi bệnh viện gần nhà.','Tôi thèm một cái máy quay phim đến không chịu được.']::text[]);

-- 100 ～てならない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('84967df5-38fc-5e83-939f-18187cd3d726', 0, 'Một cảm xúc tự nhiên trở nên mạnh mẽ, không thể kìm được (gần nghĩa với てたまらない).', ARRAY['交通事故で両親を亡くした子供がかわいそうに思えてならない。','国の家族のことが思い出されてならない。']::text[], ARRAY['Không thể không thấy thương cho những đứa trẻ mất cha mẹ vì tai nạn giao thông.','Không thể không nhớ đến gia đình ở quê nhà.']::text[]);

-- 101 ～にきまっている
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7e27e51b-904e-562a-a05d-528fe4e8ae69', 0, 'Chắc chắn là ~, đương nhiên là ~ (khẳng định dựa trên suy đoán chắc chắn của người nói, hay dùng trong văn nói).', ARRAY['ぜんぜん練習していないんだから、今度の試合は負けるにきまっている。','そんなうまい話はうそにきまっていますよ。']::text[], ARRAY['Vì chẳng luyện tập gì cả nên trận đấu lần này chắc chắn sẽ thua.','Chuyện nghe hay ho thế này chắc chắn là bịa rồi.']::text[]);

-- 102 ～にすぎない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('18880439-52b8-543f-b677-bd88f1294a7c', 0, 'Chỉ là ~ thôi, không hơn không kém — dùng để hạ thấp mức độ/tầm quan trọng của điều nói tới.', ARRAY['私は警官としてしなければならないことをしたにすぎません。','来年大地震があるというのは、うわさにすぎない。']::text[], ARRAY['Tôi chỉ làm những việc cần làm với tư cách là cảnh sát mà thôi.','Chuyện sang năm có động đất lớn chỉ là tin đồn thôi.']::text[]);

-- 103 ～に相違ない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('df73635e-28bf-55c6-83f8-0cbcee5270d6', 0, 'Chắc chắn đúng là ~, tin chắc rằng ~ không sai (cách nói trang trọng, thường dùng trong văn viết).', ARRAY['そんな非常識な要求は認められないに相違ない。','この地域の民族紛争を解決するのは難しいに相違ない。']::text[], ARRAY['Yêu cầu vô lý như thế chắc chắn không thể chấp nhận được.','Việc giải quyết xung đột sắc tộc ở khu vực này chắc chắn là khó khăn.']::text[]);

-- 104 ～に違いない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('f03c017f-002a-5d12-a087-db3a7ddcb1b2', 0, 'Chắc chắn là ~, nghĩ rằng điều đó đúng (mức độ tin tưởng cao dựa trên căn cứ).', ARRAY['かぎがない。どこかに落としたに違いない。','老人の昔話は子供には退屈に違いない。']::text[], ARRAY['Không thấy chìa khóa đâu. Chắc chắn là đã đánh rơi ở đâu đó rồi.','Chuyện xưa của người già chắc chắn là chán đối với trẻ con.']::text[]);

-- 105 ～べき／～べきだ／～べきではない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('8fce49b4-8c4a-5e20-8cf0-2d0155ca3cec', 0, 'Nên làm ~ vì đó là điều đương nhiên phải làm (nêu ý kiến, khuyến nghị của người nói).', ARRAY['書く前に注意すべき点を説明します。','どんなに親しい仲でも、借りた物はきちんと返すべきだ。']::text[], ARRAY['Trước khi viết, tôi xin giải thích những điểm cần lưu ý.','Dù thân thiết đến đâu, đồ đã mượn thì cũng nên trả lại đàng hoàng.']::text[]);

-- 106 ～（より）ほか（は）ない／～ほかしかたがない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('abacbae4-1fed-5db4-b40e-0013e84c415d', 0, 'Không còn cách nào khác ngoài việc ~.', ARRAY['だれにも頼めないから、自分でやるほかはない。','これだけ探しても見つからないのだから、あきらめるよりほかない。']::text[], ARRAY['Vì không nhờ được ai nên không còn cách nào khác ngoài tự làm.','Tìm nhiều đến thế mà không thấy thì chẳng còn cách nào khác ngoài từ bỏ.']::text[]);

-- 107 ～向きだ／～向きに／～向きの
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e59ca8a9-1ffb-5053-a5ad-da17c1a4a679', 0, 'Phù hợp, thích hợp một cách tự nhiên với đối tượng/mục đích nào đó.', ARRAY['このスキー場は初心者向きです。','これは体力が必要なので、どちらかというと若い人向きの仕事です。']::text[], ARRAY['Khu trượt tuyết này phù hợp với người mới tập.','Việc này cần thể lực nên nói chung là công việc phù hợp với người trẻ.']::text[]);

-- 108 ～向けだ／～向けに／～向けの
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('bd66dccb-10cc-5c13-9fe1-57d02a4e0dcd', 0, 'Được tạo ra/thiết kế riêng để phù hợp với một đối tượng cụ thể.', ARRAY['ここにある軽量のクリスマスカードは、みんな海外向けだ。','高齢者向けに、安全や住みやすさを考えた住宅が開発されている。']::text[], ARRAY['Số thiệp Giáng sinh nhẹ ở đây đều dành riêng cho hải ngoại.','Nhà ở dành cho người cao tuổi, chú trọng an toàn và tiện nghi, đang được phát triển.']::text[]);

-- 109 ～もの（です）か
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('c5a9b060-170e-5670-87ea-41b5e21278c7', 0, 'Quyết không ~ — thể hiện sự phủ định mạnh mẽ, thường mang tính phản bác lại ý kiến vừa nghe.', ARRAY['あの人が人の忠告なんか聞くものですか。','あの絵が名作なものか。ピカソの模倣にすぎない。']::text[], ARRAY['Người kia mà nghe lời khuyên của người khác à, quyết không đời nào.','Bức tranh đó là kiệt tác á? Chỉ là bắt chước Picasso thôi.']::text[]);

-- 110 ～ものだ／～ものではない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e78677cf-9b8c-5516-b202-da2a76b6b408', 0, 'Thể hiện cảm thán, cảm xúc sâu sắc của người nói trước một sự việc.', ARRAY['あんな大事故にあって、よく助かったものだ。','いつか京都に行ってみたいものだ。']::text[], ARRAY['Gặp tai nạn lớn thế mà vẫn được cứu sống, thật đáng kinh ngạc.','Thật muốn có ngày được đi Kyoto.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e78677cf-9b8c-5516-b202-da2a76b6b408', 1, 'Diễn tả điều được coi là lẽ thường tình, quy luật tự nhiên, ai cũng vậy.', ARRAY['地震の時は、だれでも慌てるものだ。','年末は、だれでも忙しいものだ。']::text[], ARRAY['Lúc động đất thì ai cũng hoảng loạn, đó là lẽ thường.','Cuối năm thì ai cũng bận, chuyện đương nhiên.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e78677cf-9b8c-5516-b202-da2a76b6b408', 2, 'Đưa ra lời khuyên nhẹ nhàng hoặc mệnh lệnh nhẹ (nên làm ~ / không nên làm ~).', ARRAY['人の話はよく聞くものです。','人の陰口を言うものではありません。']::text[], ARRAY['Nên chú ý lắng nghe câu chuyện của người khác.','Không nên nói xấu sau lưng người khác.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e78677cf-9b8c-5516-b202-da2a76b6b408', 3, 'Hồi tưởng lại trạng thái hoặc việc thường xảy ra trong quá khứ.', ARRAY['子供のころ、いたずらをして、よく父に叱られたものだ。','この辺は、昔は静かだったものだ。']::text[], ARRAY['Hồi bé nghịch ngợm nên hay bị bố mắng.','Khu này ngày xưa yên tĩnh lắm.']::text[]);

-- 111 ～わけだ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5f22e3d0-6d15-5622-a084-cd95dde9c59f', 0, 'Kết luận đó là đương nhiên vì đã có lý do rõ ràng (suy luận logic từ một sự việc đã biết).', ARRAY['暗いわけだ。蛍光灯が１本切れている。','ジョンさんは、お母さんが日本人ですから、日本語が上手なわけです。']::text[], ARRAY['Tối là phải rồi. Một bóng đèn huỳnh quang bị cháy.','Anh John có mẹ là người Nhật nên giỏi tiếng Nhật là điều đương nhiên.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5f22e3d0-6d15-5622-a084-cd95dde9c59f', 1, 'Diễn giải lại, tóm tắt một sự việc theo cách hiểu là như vậy, dựa trên diễn biến trước đó.', ARRAY['５パーセントの値引きというと、１万円の物は9500円になるわけですね。','はじめは観光旅行のつもりで日本へ遊びに来たんですが、日本が好きになり、とうとう10年も日本に住んでしまったわけです。']::text[], ARRAY['Nói là giảm giá 5% tức là món hàng 1 vạn yên sẽ còn 9500 yên nhỉ.','Ban đầu định chỉ đi du lịch ngắm cảnh ở Nhật thôi, nhưng rồi thích Nhật Bản, thế là cuối cùng đã sống tới 10 năm ở đó.']::text[]);

-- 112 ～わけではない／～わけでもない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e7e02dc7-2373-5e25-9d44-1243f2a01dd7', 0, 'Không phải là ~ hoàn toàn, không nhất thiết là ~ (phủ định một phần, không phủ định tuyệt đối).', ARRAY['生活に困っているわけではないが、貯金する余裕はない。','甘い物が嫌いなわけではありませんが、ダイエットしているんです。']::text[], ARRAY['Không phải là cuộc sống khó khăn, nhưng cũng không có dư để tiết kiệm.','Không phải là ghét đồ ngọt, nhưng tôi đang ăn kiêng.']::text[]);

-- 113 ～っけ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('c4463748-e964-5f16-9d62-7540e094f1a0', 0, 'Dùng khi cố nhớ lại hoặc xác nhận lại một điều vừa nhớ ra, chỉ dùng trong văn nói.', ARRAY['彼にはまだパーティーの場所を知らせていなかったっけ。','そうだ。今日はお母さんの誕生日だっけ。']::text[], ARRAY['Hình như tôi vẫn chưa báo cho anh ấy địa điểm tiệc thì phải.','À đúng rồi. Hôm nay là sinh nhật mẹ phải không nhỉ.']::text[]);

-- 114 ～とか
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('c8ec66a0-1068-5a52-96db-78a2cb83c363', 0, 'Nghe nói là ~ — truyền đạt lại thông tin gián tiếp, không chắc chắn hoàn toàn.', ARRAY['新聞によると、国内線の飛行機運賃が上がるとか。','昨日はこの冬一番の寒さだったとか。']::text[], ARRAY['Theo báo thì nghe nói giá vé máy bay nội địa sẽ tăng.','Nghe nói hôm qua là ngày lạnh nhất mùa đông này.']::text[]);

-- 115 ～どころではない／～どころではなく
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d894b666-2951-51db-8b94-2f53242c081a', 0, 'Không có tâm trí/điều kiện để làm ~ vì có lý do, hoàn cảnh khác quan trọng/cấp bách hơn.', ARRAY['人の仕事を手伝うどころではありません。自分の仕事も間に合わないんです。','せっかく海へ行ったのに、寒くて泳ぐどころではなかった。']::text[], ARRAY['Chẳng còn hơi sức đâu mà giúp việc người khác, việc của mình còn chưa xong kịp đây.','Khó khăn lắm mới đi biển được, thế mà lạnh đến mức chẳng thể bơi nổi.']::text[]);

-- 116 ～からして
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('86c19e26-a4d3-5bb3-9203-31c08e38a1af', 0, 'Đưa ra một ví dụ tiêu biểu để ngầm khẳng định những điều khác cũng tương tự (ngay cả ~ đã thế thì...).', ARRAY['彼は礼儀を知らない。あいさつからして、きちんとしていない。','田舎は空気からして違う。']::text[], ARRAY['Anh ta chẳng biết lễ nghi gì cả. Ngay cả chào hỏi cũng không đàng hoàng.','Ở quê thì ngay cả không khí cũng đã khác rồi.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('86c19e26-a4d3-5bb3-9203-31c08e38a1af', 1, 'Dựa vào điều đó để phán đoán, suy luận ra một kết luận.', ARRAY['窓ガラスが破られていることからして、泥棒はここから行ったに違いない。','彼の健康状態からして、登山は無理だろう。']::text[], ARRAY['Nhìn kính cửa sổ bị vỡ như vậy, chắc chắn kẻ trộm đã đột nhập từ đây.','Xét theo tình trạng sức khỏe của anh ta thì leo núi chắc là không nổi đâu.']::text[]);

-- 117 ～からすると／～からすれば
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e9359294-7fc5-5d5f-bb3c-1be7c173e325', 0, 'Nhìn từ lập trường, góc độ của ai/cái gì đó.', ARRAY['親からすると、子供はいくつになっても子供で、心配なものだ。','日本人からすれば当たり前なことでも、外国人にとっては変だと思うこともある。']::text[], ARRAY['Với bố mẹ thì con cái dù lớn đến đâu vẫn là con trẻ, vẫn đáng lo.','Có những việc người Nhật thấy đương nhiên nhưng người nước ngoài lại thấy lạ lùng.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e9359294-7fc5-5d5f-bb3c-1be7c173e325', 1, 'Dựa vào điều đó mà phán đoán, suy luận ra.', ARRAY['あの車は形からすると10年ぐらい前のものだと思う。','彼女の能力からすれば、A大学に十分合格できるだろう。']::text[], ARRAY['Nhìn hình dáng chiếc xe kia, tôi nghĩ nó là đồ từ khoảng 10 năm trước.','Xét năng lực của cô ấy thì chắc đủ sức đỗ đại học A.']::text[]);

-- 118 ～からには／～からは
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5373979f-3266-57de-8d7e-5e91c88e4b21', 0, 'Vì đã ~ rồi thì đương nhiên phải/nên làm điều tương ứng ở vế sau.', ARRAY['試合に出るからには、勝ちたい。','約束したからには、守らなければいけない。']::text[], ARRAY['Đã tham gia thi đấu rồi thì muốn thắng.','Đã hứa rồi thì phải giữ lời.']::text[]);

-- 119 ～ことだから
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e3bf3c4f-df54-5355-8d2e-d40a45643de8', 0, 'Vì là (người/việc) mà ai cũng biết rõ tính cách/đặc điểm, nên có thể suy đoán ra điều ở vế sau.', ARRAY['子供のことだから、少しぐらいいたずらをしても仕方がないです。','あなたのことだからきっといい論文が書けると思います。']::text[], ARRAY['Vì là trẻ con nên có nghịch một chút cũng chẳng thể trách được.','Vì là bạn nên tôi tin chắc sẽ viết được một bài luận văn hay.']::text[]);

-- 120 ～だけ／～だけあって／～だけに／～だけの
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('a67fbf7f-eff3-591d-8f87-3fc1d02d3ebc', 0, 'Đúng là xứng đáng, phù hợp với ~ (khen ngợi kết quả tương xứng với nguyên nhân/điều kiện).', ARRAY['この大学は歴史が長いだけあって伝統がある。','彼女はアメリカに留学しただけに英語がうまいね。']::text[], ARRAY['Trường đại học này quả đúng là có bề dày truyền thống tương xứng với lịch sử lâu đời.','Đúng là từng du học ở Mỹ nên tiếng Anh giỏi thật.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('a67fbf7f-eff3-591d-8f87-3fc1d02d3ebc', 1, 'Chính vì ~ nên càng ~ (nhấn mạnh mức độ tăng thêm do lý do đó).', ARRAY['今日の試合は優勝がかかっているだけに大勢のファンが詰めかけ熱烈な応援をしていた。','昨年はみかんが不作で、値段が高かっただけに今年の豊作がうれしい。']::text[], ARRAY['Chính vì trận đấu hôm nay quyết định nhà vô địch nên càng đông fan hâm mộ kéo đến cổ vũ nhiệt tình.','Chính vì năm ngoái quýt mất mùa, giá cao nên năm nay được mùa lại càng vui hơn.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('a67fbf7f-eff3-591d-8f87-3fc1d02d3ebc', 2, 'Làm hết mức có thể, đến giới hạn tối đa (không giữ lại gì).', ARRAY['考えるだけ考えたが結論は出なかった。','欲しいだけ本が買えたらどんなにいいだろう。']::text[], ARRAY['Đã nghĩ hết sức có thể mà vẫn chưa ra được kết luận.','Giá mà mua được sách nhiều đến mức mong muốn thì tốt biết mấy.']::text[]);

-- 121 ～にあたって／～に当たり
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('407e941f-d553-5cdb-a59c-49c319bfa011', 0, 'Vào lúc, trong dịp làm một việc quan trọng/đặc biệt nào đó.', ARRAY['開会にあたって、ひとことごあいさつ申し上げます。','新製品を開発するにあたり、強力なプロジェクトチームが作られた。']::text[], ARRAY['Nhân dịp khai mạc, tôi xin có đôi lời chào mừng.','Khi bắt tay phát triển sản phẩm mới, một đội dự án hùng hậu đã được thành lập.']::text[]);

-- 122 ～にかけては／～にかけても
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5e847563-7cc0-52e9-bf72-ac35f6cd709d', 0, 'Nếu nói riêng về mặt/lĩnh vực đó (thường kèm đánh giá tích cực, khẳng định sự vượt trội).', ARRAY['数学にかけては、彼女はクラスでいつも一番だった。','走ることにかけては、だれにも負けないつもりだ。']::text[], ARRAY['Nếu nói về môn Toán thì cô ấy luôn đứng nhất lớp.','Về khoản chạy thì tôi quyết không thua ai.']::text[]);

-- 123 ～に際して／～に際し／～に際しての
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('101950ca-f9dc-5e0a-af92-d5a60e0501db', 0, 'Vào lúc bắt đầu hoặc đang tiến hành một việc quan trọng, đặc biệt (cách nói trang trọng).', ARRAY['留学に際して、先生や友人から励ましの言葉をもらった。','帰国に際し、お世話になった人にあいさつの手紙を出した。']::text[], ARRAY['Khi chuẩn bị du học, tôi đã nhận được nhiều lời động viên từ thầy cô và bạn bè.','Khi về nước, tôi đã gửi thư chào những người đã giúp đỡ mình.']::text[]);

-- 124 ～に先立って／～に先立ち／～に先立つ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('4742bf49-01e0-5175-8ff8-301d815080a7', 0, 'Trước khi làm việc gì, tiến hành trước một việc khác có liên quan (cách nói trang trọng).', ARRAY['映画の一般公開に先立って、主演女優のサイン会が開かれた。','入社試験に先立ち、会社説明会が行われた。']::text[], ARRAY['Trước khi công chiếu rộng rãi bộ phim, buổi ký tặng của nữ diễn viên chính đã được tổ chức.','Trước kỳ thi tuyển vào công ty, buổi giới thiệu về công ty đã được tổ chức.']::text[]);

-- 125 ～にしたら／～にすれば／～にしても
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('96e95e99-7c98-58e3-92c5-623757f945c1', 0, 'Nếu đứng trên lập trường, suy nghĩ của ~ mà nói (tưởng tượng cảm nhận từ góc nhìn của đối tượng đó).', ARRAY['あの人にしたら、私たちの親切はかえって迷惑かもしれません。','学生にすれば、休みは長ければ長いほどいいだろう。']::text[], ARRAY['Đứng ở góc độ của người đó, có khi sự tốt bụng của chúng ta lại thành phiền phức.','Đối với học sinh, kỳ nghỉ chắc càng dài càng thích.']::text[]);

-- 126 ～につき
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('da9f9d45-7f3a-5776-aad7-9e45bf7f6f6e', 0, 'Vì ~ (cách nói trang trọng, thường dùng trong thông báo, văn bản).', ARRAY['雨天につき、試合は延期いたします。','店内改装につき、しばらく休業いたします。']::text[], ARRAY['Vì trời mưa nên trận đấu sẽ được hoãn lại.','Vì đang sửa sang cửa hàng nên chúng tôi tạm nghỉ bán trong một thời gian.']::text[]);

-- 127 ～につけ／～につけて（は）／～につけても
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ba392bc6-f0bd-5d28-ad2e-b15b6552af4c', 0, 'Mỗi lần làm/gặp việc gì đó thì lại nảy sinh cảm xúc, suy nghĩ nào đó.', ARRAY['家族の写真を見るにつけ、会いたくてたまらなくなる。','戦争のニュースを聞くにつけ、心が痛む。']::text[], ARRAY['Mỗi lần nhìn ảnh gia đình, tôi lại nhớ đến mức không chịu nổi.','Mỗi lần nghe tin chiến tranh, lòng tôi lại quặn đau.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ba392bc6-f0bd-5d28-ad2e-b15b6552af4c', 1, 'Dù trong trường hợp nào (cả hai vế đối lập) cũng đều xảy ra điều tương tự.', ARRAY['先輩の活躍を見るにつけ聞くにつけ、心強くなる。','暑いにつけ寒いにつけ、うちのおばあさんは体の調子が悪いと言う。']::text[], ARRAY['Dù nhìn hay nghe về những thành tích của các tiền bối, tôi đều thấy vững tâm hơn.','Dù nóng hay lạnh, bà tôi cũng đều than là người không khỏe.']::text[]);

-- 128 ～のもとで／～のもとに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ed84433f-99f4-5276-a16a-d6dad066f4ae', 0, 'Dưới sự chỉ đạo, ảnh hưởng hoặc điều kiện của ~.', ARRAY['鈴木教授のご指導のもとで、卒業論文を完成させた。','子供の人権は法のもとに守られています。']::text[], ARRAY['Dưới sự hướng dẫn của giáo sư Suzuki, tôi đã hoàn thành khóa luận tốt nghiệp.','Quyền của trẻ em được bảo vệ dưới pháp luật.']::text[]);

-- 129 ～はともかく（として）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('1b600119-47d5-5f0d-8bdd-b2ac7818652b', 0, 'Tạm gác việc đó sang một bên, chưa bàn đến, trước hết hãy nói về điều khác.', ARRAY['この洋服は、デザインはともかく、色がよくない。','私は、話すことはともかく、書くことは苦手だ。']::text[], ARRAY['Bộ quần áo này, tạm chưa bàn đến thiết kế, màu sắc thì không đẹp.','Tôi thì việc nói tạm gác lại, chứ viết là tôi kém lắm.']::text[]);

-- 130 ～をきっかけに（して）／～をきっかけとして
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ae305f71-3dbf-58bf-8ca6-0e11a816b5e7', 0, 'Lấy một sự việc (thường là tình cờ) làm cơ hội, khởi đầu để một việc khác bắt đầu hoặc thay đổi.', ARRAY['留学をきっかけに、自分の国についていろいろ考えるようになった。','旅行をきっかけにして、木村さんと親しくなりました。']::text[], ARRAY['Nhân dịp đi du học, tôi bắt đầu suy nghĩ nhiều hơn về đất nước mình.','Nhờ chuyến du lịch mà tôi trở nên thân thiết với anh Kimura.']::text[]);

-- 131 ～を契機に（して）／～を契機として
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('454ba874-b67b-5748-a136-62b0e7eef704', 0, 'Nhân một sự kiện làm cơ hội, bước ngoặt cho một sự thay đổi lớn, rõ rệt.', ARRAY['オイルショックを契機に新エネルギーの研究が進められた。','新製品の開発を契機として、大きく会社が発展した。']::text[], ARRAY['Nhân cơ hội cuộc khủng hoảng dầu mỏ, việc nghiên cứu năng lượng mới đã được đẩy mạnh.','Nhân việc phát triển sản phẩm mới, công ty đã phát triển mạnh mẽ.']::text[]);

-- 132 ～を～として／～を～とする／～を～とした
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e1ce5d7d-ca68-5f88-90d1-45fb8711be9f', 0, 'Lấy ~ làm ~ (xác định vai trò, mục đích, tiêu chuẩn của một đối tượng).', ARRAY['陳さんを先生として、中国語の勉強会を開いた。','同窓会は卒業生の交流を目的とする集まりです。']::text[], ARRAY['Chúng tôi đã mở lớp học tiếng Trung, lấy anh Trần làm giáo viên.','Buổi họp mặt cựu học sinh là buổi tụ họp lấy mục đích là giao lưu giữa các cựu sinh viên.']::text[]);

-- 133 ～あげく（に）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('eaa03502-8b37-57df-a862-755d8293bb6b', 0, 'Sau khi trải qua nhiều việc/cố gắng, rốt cuộc dẫn đến kết quả (thường là không như ý).', ARRAY['さんざん迷ったあげく、大学院には行かないことにした。','その男はお金に困ったあげく、銀行強盗を計画した。']::text[], ARRAY['Sau khi lưỡng lự rất nhiều, rốt cuộc tôi đã quyết định không học lên cao học.','Người đàn ông đó vì khốn khổ vì tiền, rốt cuộc đã lên kế hoạch cướp ngân hàng.']::text[]);

-- 134 ～以上（は）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('50f67271-14e8-5fbd-9dbe-87e9273a6c52', 0, 'Vì đã ~ (ở một tình huống, trách nhiệm nào đó) thì đương nhiên phải làm điều ở vế sau.', ARRAY['日本に住んでいる以上、日本の法律を守らなければならない。','約束した以上、必ず守ってください。']::text[], ARRAY['Đã sống ở Nhật thì phải tuân thủ pháp luật Nhật Bản.','Đã hứa rồi thì nhất định phải giữ lời.']::text[]);

-- 135 ～上は
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7c0e4d39-7a24-50a6-84c4-7188abda0b4c', 0, 'Vì đã ~ (một sự việc chắc chắn xảy ra) rồi thì đương nhiên phải làm gì đó (cách nói trang trọng).', ARRAY['契約を結ぶ上は、条件を慎重に検討すべきである。','弁護士になると決めた上は、苦しくても頑張らなければならない。']::text[], ARRAY['Đã ký hợp đồng thì cần xem xét kỹ lưỡng các điều khoản.','Đã quyết tâm trở thành luật sư thì dù vất vả cũng phải cố gắng.']::text[]);

-- 136 ～ことなく
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('067c170e-f9d0-5751-877c-2255b4b26fe3', 0, 'Không làm ~ (cách nói trang trọng, thường dùng trong văn viết thay cho ~ないで).', ARRAY['ロボットは24時間休むことなく働いている。','あの子はあきることなく、コンピューターゲームに熱中している。']::text[], ARRAY['Robot làm việc 24 tiếng không nghỉ.','Đứa trẻ đó say mê chơi game không biết chán.']::text[]);

-- 137 ～際（は）／～際に
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('a37a2314-3d3c-5d43-8d82-e29c4f5a96ec', 0, 'Vào lúc, trong trường hợp ~ (cách nói trang trọng hơn とき).', ARRAY['帰国の際、保証人の家にあいさつに行った。','パスポートを申請する際に必要なものを教えてください。']::text[], ARRAY['Lúc về nước, tôi đã đến chào nhà người bảo lãnh.','Xin hãy cho tôi biết những thứ cần thiết khi xin cấp hộ chiếu.']::text[]);

-- ============ grammar_points enrichment (memory_tip / comparison_note / common_mistake) ============

update grammar_points set memory_tip = 'くせに luôn mang theo thái độ khinh thường, chê trách của người nói — nhớ nó là "dù... vậy mà còn..." với giọng bực bội.', comparison_note = 'Khác のに (chỉ nêu sự tương phản trung tính, không phán xét) — くせに chỉ dùng khi người nói có ý chê bai, không hài lòng về chủ thể.', common_mistake = 'Dùng くせに để nói khiêm tốn về bản thân hoặc dùng với người trên/cấp trên — thực ra くせに mang sắc thái xấc xược, không phù hợp khi nói về mình hay người cần tôn trọng.' where id = 'a42e83c5-1b8c-551a-9e00-65c1a3b54d23';
update grammar_points set memory_tip = 'こと + から = "từ sự việc đó mà..." — ことから luôn nêu một hiện tượng/chứng cứ quan sát được rồi mới suy ra kết luận.', comparison_note = 'Khác ので (chỉ nêu lý do đơn thuần) — ことから thường dùng khi kết luận được suy ra từ một sự việc/quan sát cụ thể, hay xuất hiện trong văn giải thích, khoa học.', common_mistake = 'Nhầm ことから với から thông thường rồi dùng tùy tiện trong hội thoại đời thường — ことから thiên về văn viết, giải thích nguồn gốc, ít dùng để nói lý do cá nhân đơn giản.' where id = 'd9c79c98-8177-5019-8af1-13df14f67502';
update grammar_points set memory_tip = 'ことに（は）luôn đứng ĐẦU câu, nêu cảm xúc trước rồi mới kể sự việc — như một tiếng "thật đáng..." mở đầu.', comparison_note = 'Khác ものだ (nghĩa cảm thán, đặt cuối câu) — ことには đặt tính từ/cảm xúc lên đầu câu để nhấn mạnh trước khi kể chi tiết sự việc.', common_mistake = 'Đặt ことに ở giữa hoặc cuối câu thay vì đầu câu — mẫu này bắt buộc mở đầu bằng cảm xúc (驚いたことに、うれしいことに...) rồi mới đến nội dung sự việc.' where id = '67c058b5-f614-5748-8785-335198fc0a61';
update grammar_points set memory_tip = '上 gắn sau danh từ trừu tượng (歴史上、法律上...) để chỉ "xét theo phương diện/khía cạnh đó".', comparison_note = 'Khác 点で (cũng nghĩa "về mặt") — ～上 mang tính trang trọng, cố định hơn, chỉ đi được với một số danh từ nhất định như 歴史上、法律上、理論上、健康上.', common_mistake = 'Ghép 上 với danh từ cụ thể tùy ý — 上 theo mẫu này chỉ tự nhiên với các danh từ trừu tượng, mang tính hệ thống/lĩnh vực, không dùng cho danh từ chỉ vật cụ thể.' where id = '1c9fbc04-eceb-5c40-86a5-6ff11df13ed5';
update grammar_points set memory_tip = '末（すえ）nghĩa gốc là "cuối cùng, tận cùng" — nhớ là luôn đi sau một quá trình DÀI (suy nghĩ, tranh luận, cố gắng).', comparison_note = 'Khác あげく（に）(mục cùng nghĩa "sau khi trải qua") — 末に mang sắc thái trung tính, còn あげく thường ngụ ý kết quả không như ý, tiêu cực.', common_mistake = 'Dùng た末に cho kết quả xảy ra ngay lập tức, không qua quá trình dài — mẫu này chỉ hợp khi có một quá trình đắn đo, cố gắng kéo dài trước đó.' where id = '0bdd119f-70b9-5011-8e5c-769cac70abee';
update grammar_points set memory_tip = 'たところ = làm xong việc rồi mới TÌNH CỜ phát hiện ra điều tiếp theo — không phải quan hệ nhân quả tất yếu.', comparison_note = 'Khác たとたん（に）(ngay khi vừa... thì lập tức...) — たところ chỉ đơn thuần nối "làm A rồi thì (phát hiện/xảy ra) B", không nhấn mạnh tính tức thời như たとたん.', common_mistake = 'Dùng たところ theo nghĩa điều kiện giả định như "nếu làm..." — たところ chỉ nói về việc đã thực sự xảy ra trong quá khứ, không phải giả định.' where id = '8f5a53ef-c933-5d66-9ede-2a00dec9377e';
update grammar_points set memory_tip = 'ついで nghĩa là "tiện thể, nhân lúc" — nhớ bằng hình ảnh "đi chợ tiện thể ghé mua thêm".', comparison_note = 'Khác がてら (cũng nghĩa tiện thể nhưng trang trọng/văn viết hơn) — ついでに thông dụng hơn, dùng được cho cả việc đã làm xong lẫn đang định làm.', common_mistake = 'Dùng ついでに khi hai việc có tầm quan trọng ngang nhau — bản chất ついでに hàm ý một việc là chính, một việc chỉ là "tiện thể" phụ thêm, không nên dùng khi cả hai đều là mục đích chính.' where id = 'da25d60c-c1c4-559b-a1c2-522b362cab91';
update grammar_points set memory_tip = 'Nhớ というと／といえば như một "cầu nối liên tưởng": nhắc đến A là nghĩ ngay đến B nổi tiếng/liên quan nhất.', comparison_note = 'Khác について (chỉ nêu chủ đề trung tính) — というと／といえば luôn có sắc thái liên tưởng, gợi nhớ tự nhiên đến một ví dụ hay kỷ niệm liên quan.', common_mistake = 'Dùng というと／といえば để hỏi định nghĩa một từ hoàn toàn xa lạ — mẫu này chỉ hợp khi cả hai bên đã biết chủ đề, một bên chỉ nêu điều liên tưởng chứ không giải thích khái niệm.' where id = '3040e16c-734e-5a29-ad1c-4d5490083ddb';
update grammar_points set memory_tip = 'といったら luôn đi kèm cảm xúc dâng trào (ngạc nhiên, than phiền, thán phục) về MỨC ĐỘ của một điều gì.', comparison_note = 'Khác ほど (so sánh mức độ khách quan) — といったら mang tính cảm thán chủ quan mạnh, thường không thể diễn đạt hết bằng lời (口で言い表せないほど).', common_mistake = 'Dùng といったら cho những câu tường thuật khách quan, không cảm xúc — mẫu này chỉ tự nhiên khi người nói thực sự ngạc nhiên/xúc động về điều đó.' where id = '23d271c5-1079-5eba-9172-47540aa60bea';
update grammar_points set memory_tip = 'というより = "nói là... nhưng thực ra..." — luôn dùng để ĐÍNH CHÍNH lại cách diễn đạt vừa nêu bằng một từ khác chính xác hơn.', comparison_note = 'Khác より (so sánh đơn thuần giữa hai đối tượng) — というより so sánh hai CÁCH DIỄN ĐẠT về cùng một sự việc, chọn cách nào đúng hơn chứ không so sánh hai sự vật khác nhau.', common_mistake = 'Dùng というより để so sánh hai sự vật hoàn toàn khác biệt, không liên quan — mẫu này chỉ hợp khi đang mô tả LẠI cùng một đối tượng bằng từ ngữ chính xác hơn.' where id = '7aba60a4-1e30-56cb-84b3-8ff2770dc4c8';
update grammar_points set memory_tip = 'Nhớ công thức kép: [động từ điều kiện ば] + [cùng động từ ở thể từ điển] + ほど — lặp lại động từ để nhấn mạnh "càng...càng".', comparison_note = 'Khác ほど đứng một mình (không cần vế điều kiện ば) — ば～ほど nhấn mạnh MỐI QUAN HỆ TỈ LỆ giữa hai mức độ thay đổi cùng lúc.', common_mistake = 'Dùng hai động từ khác nhau ở hai vế thay vì lặp lại cùng một động từ/tính từ — cấu trúc chuẩn bắt buộc vế ば và vế ほど phải cùng một từ gốc.' where id = 'f8efbc69-a93b-5167-aa1c-8eefb58ec8ba';
update grammar_points set memory_tip = 'ほど đơn (không có ば) vẫn giữ nghĩa "càng...càng..." nhưng ngắn gọn hơn ば～ほど, thường đi với tính từ/danh từ.', comparison_note = 'Khác ば～ほど (cấu trúc đầy đủ có điều kiện ば) — ほど đơn giản hơn về hình thức nhưng nghĩa tương đương, hay dùng khi chủ ngữ là danh từ so sánh (太っているほど).', common_mistake = 'Nhầm ほど kiểu so sánh tỉ lệ này với ほど chỉ mức độ cực đại (đến mức...) — cần phân biệt theo ngữ cảnh có hai mức độ song song thay đổi hay chỉ một mức độ đơn.' where id = '51643c2b-e39f-569a-bf44-59fd6b1b2c98';
update grammar_points set memory_tip = 'かのようだ nhấn mạnh SỰ THẬT không phải vậy, chỉ là "trông có vẻ như" — chữ か mang nghĩa hoài nghi, không chắc chắn.', comparison_note = 'Khác ようだ đơn thuần (có thể dùng cho cả suy đoán có căn cứ thật) — かのようだ luôn hàm ý điều đó KHÔNG đúng sự thật, chỉ là vẻ bề ngoài đánh lừa.', common_mistake = 'Dùng かのようだ để suy đoán một điều có khả năng là sự thật — mẫu này chỉ hợp khi người nói biết chắc thực tế KHÁC với những gì được mô tả.' where id = '2048a890-2bd9-57ca-ba42-bccc0bd9072a';
update grammar_points set memory_tip = 'つつある = ます形 + つつある, nhớ như "đang từng bước (dần dần)" thay vì đang diễn ra tức thời như ている.', comparison_note = 'Khác ている (tiến hành đơn thuần, có thể tức thời hoặc kéo dài) — つつある chỉ dùng cho THAY ĐỔI dần dần theo thời gian và chủ yếu xuất hiện trong văn viết.', common_mistake = 'Dùng つつある với động từ chỉ hành động tức thời, không có tính biến đổi dần dần (như 死ぬ、座る) — mẫu này chỉ hợp với động từ chỉ quá trình thay đổi từ từ như 回復する、改善される.' where id = '43c4dc99-b104-5bb9-9b14-893e801c6329';
update grammar_points set memory_tip = 'たまらない nghĩa gốc là "không chịu đựng nổi" — ghép sau て形 của cảm xúc/cảm giác để nói cảm xúc đó quá mạnh không kìm được.', comparison_note = 'Gần nghĩa với てならない nhưng てたまらない/てしようがない dùng được cả với cảm giác thể chất (痛い、眠い) lẫn cảm xúc, còn てならない thiên về cảm xúc/suy nghĩ tự nhiên nảy sinh hơn.', common_mistake = 'Dùng mẫu này với chủ ngữ ngôi thứ ba mà không có căn cứ suy đoán — mẫu てたまらない giới hạn chủ ngữ ở ngôi thứ nhất (hoặc cần thêm ようだ/そうだ khi nói về người khác).' where id = 'a6d6b6ca-b76e-5e42-8987-7e7c6bc3db60';
update grammar_points set memory_tip = 'てならない nhớ như "không cách nào không...", cảm xúc tự nhiên trào lên mà bản thân không kiểm soát được.', comparison_note = 'Gần nghĩa てたまらない nhưng てならない thường dùng với động từ chỉ cảm giác/suy nghĩ nảy sinh tự nhiên (思える、思い出される、心配だ) hơn là cảm giác thể chất trực tiếp.', common_mistake = 'Dùng てならない với động từ ý chí (như 食べる、行く) — mẫu này chỉ tự nhiên với tính từ cảm xúc hoặc động từ thể bị động/tự phát (思われる、感じられる).' where id = '84967df5-38fc-5e83-939f-18187cd3d726';
update grammar_points set memory_tip = 'きまっている gốc từ 決まる (đã được quyết định) — nhớ là "chắc chắn 100% trong đầu người nói", hay dùng trong văn nói.', comparison_note = 'Khác に違いない/に相違ない (trang trọng, dùng cả văn viết) — にきまっている mang tính khẩu ngữ, chủ quan và đôi khi hơi võ đoán hơn.', common_mistake = 'Dùng にきまっている trong văn bản trang trọng, báo cáo chính thức — mẫu này thiên về khẩu ngữ nên ưu tiên に違いない hoặc に相違ない trong văn viết.' where id = '7e27e51b-904e-562a-a05d-528fe4e8ae69';
update grammar_points set memory_tip = 'すぎない gốc từ 過ぎる (vượt quá) ở thể phủ định — nghĩa đen là "không vượt quá..." tức chỉ dừng ở mức đó thôi, không hơn.', comparison_note = 'Khác だけだ (chỉ đơn thuần giới hạn số lượng/phạm vi) — にすぎない còn mang thêm sắc thái đánh giá thấp, hạ bệ tầm quan trọng của điều được nói tới.', common_mistake = 'Dùng にすぎない với sắc thái khen ngợi, tích cực — mẫu này gần như luôn mang nghĩa hạ thấp, chê ít ỏi/tầm thường, không hợp ngữ cảnh khen.' where id = '18880439-52b8-543f-b677-bd88f1294a7c';
update grammar_points set memory_tip = '相違（そうい）nghĩa là "sai khác" — に相違ない = "không có sự sai khác", tức chắc chắn đúng, là cách nói trang trọng của に違いない.', comparison_note = 'Gần như đồng nghĩa với に違いない nhưng に相違ない trang trọng hơn, thường xuất hiện trong văn viết, báo cáo, hiếm dùng trong hội thoại thường ngày.', common_mistake = 'Dùng に相違ない trong hội thoại thân mật hàng ngày — nghe rất cứng nhắc, nên đổi sang に違いない hoặc にきまっている cho tự nhiên hơn.' where id = 'df73635e-28bf-55c6-83f8-0cbcee5270d6';
update grammar_points set memory_tip = '違い（ちがい）nghĩa là "khác biệt" — に違いない = "không có khác biệt (so với suy đoán)", tức chắc chắn đúng như vậy.', comparison_note = 'So với に相違ない (trang trọng hơn) và にきまっている (khẩu ngữ hơn) thì に違いない là mức trung tính, dùng được cả văn nói lẫn văn viết.', common_mistake = 'Dùng に違いない khi thực ra không có căn cứ suy luận nào, chỉ là mong muốn chủ quan — mẫu này cần dựa trên một dấu hiệu/bằng chứng cụ thể để suy luận, không phải ước muốn đơn thuần.' where id = 'f03c017f-002a-5d12-a087-db3a7ddcb1b2';
update grammar_points set memory_tip = 'べき nối trực tiếp sau động từ thể từ điển (riêng する có thể thành すべき) — nhớ như lời khuyên đạo đức "nên/phải làm vì lẽ thường".', comparison_note = 'Khác なければならない (nghĩa vụ bắt buộc, không làm sẽ có hậu quả) — べき mang tính chất khuyên nhủ dựa trên đạo lý, lẽ phải chung, không hẳn là quy định bắt buộc.', common_mistake = 'Chia べき theo thì quá khứ không đúng cách hoặc gắn べき sau danh từ/tính từ — べき chỉ nối trực tiếp sau động từ thể từ điển, không có dạng khác.' where id = '8fce49b4-8c4a-5e20-8cf0-2d0155ca3cec';
update grammar_points set memory_tip = 'ほか nghĩa "ngoài ra" + ない (không có) = "không có [cách nào khác] ngoài việc..." — hình dung như đường cùng, chỉ còn một lối đi.', comparison_note = 'Gần nghĩa しかない (N3, thông dụng hơn trong hội thoại) — ほかない/ほかはない trang trọng hơn một chút, hay xuất hiện trong văn viết hoặc lời nói nghiêm túc.', common_mistake = 'Dùng ほかない với danh từ trực tiếp mà không qua động từ — mẫu này chuẩn phải đi sau động từ thể từ điển diễn tả hành động buộc phải làm.' where id = 'abacbae4-1fed-5db4-b40e-0013e84c415d';
update grammar_points set memory_tip = '向き（むき）gốc nghĩa "hướng" — nhớ là tính chất VỐN CÓ của sự vật tự nhiên phù hợp với ai đó, không phải cố ý tạo ra.', comparison_note = 'Khác 向けだ (được CHỦ ĐÍCH làm ra để phù hợp với đối tượng) — 向き chỉ đơn thuần mô tả đặc điểm tự nhiên phù hợp, còn 向け nhấn mạnh mục đích thiết kế có chủ đích.', common_mistake = 'Dùng lẫn lộn 向き và 向け cho nhau — cần phân biệt: 向き là "hợp với" một cách tự nhiên (初心者向き), còn 向け là "làm ra cho" một đối tượng cụ thể (子供向けの本).' where id = 'e59ca8a9-1ffb-5053-a5ad-da17c1a4a679';
update grammar_points set memory_tip = '向け nhớ như "hướng đến, nhắm đến" đối tượng cụ thể — luôn có ý nghĩa được tạo ra/thiết kế CÓ CHỦ ĐÍCH.', comparison_note = 'Khác 向きだ (đặc điểm tự nhiên phù hợp, không chủ đích) — 向け nhấn mạnh sản phẩm/nội dung được làm RA để phục vụ riêng cho nhóm đối tượng đó.', common_mistake = 'Dùng 向けだ để mô tả tính chất tự nhiên vốn có (không phải do thiết kế) — trường hợp đó nên dùng 向きだ mới đúng sắc thái.' where id = 'bd66dccb-10cc-5c13-9fe1-57d02a4e0dcd';
update grammar_points set memory_tip = 'もの（です）か đọc lên giọng nghi vấn nhưng thực chất là phủ định MẠNH — càng gằn giọng thì phủ định càng dứt khoát.', comparison_note = 'Khác わけがない (phủ định logic, khách quan) — ものか mang tính cảm xúc, phản bác trực tiếp một ý kiến/câu hỏi vừa nghe, hay dùng trong tranh luận, cãi lại.', common_mistake = 'Dùng ものか trong văn viết trang trọng hoặc khi nói với người trên — mẫu này rất suồng sã, thể hiện cảm xúc mạnh nên chỉ hợp trong hội thoại thân mật.' where id = 'c5a9b060-170e-5670-87ea-41b5e21278c7';
update grammar_points set memory_tip = 'ものだ có tới 4 sắc thái (cảm thán / lẽ thường / khuyên bảo / hồi tưởng) — nhớ theo loại từ đứng trước: quá khứ+ものだ thường là hồi tưởng, từ điển+ものだ là khuyên bảo.', comparison_note = 'Nghĩa "khuyên bảo" của ものだ gần với べき nhưng ものだ nhẹ nhàng hơn, mang tính chuẩn mực chung ("người ta nên..."), còn べき thiên về ý kiến cá nhân mạnh mẽ hơn.', common_mistake = 'Nhầm lẫn 4 nghĩa của ものだ do không để ý loại từ/thì đứng trước — cần xác định rõ đang ở thì nào, tính từ hay động từ để chọn đúng sắc thái (cảm thán, lẽ thường, khuyên hay hồi tưởng).' where id = 'e78677cf-9b8c-5516-b202-da2a76b6b408';
update grammar_points set memory_tip = 'わけ nghĩa gốc là "lý do, đầu đuôi" — わけだ nhớ như "vậy ra là...", kết luận tất yếu rút ra từ một sự việc/thông tin đã biết.', comparison_note = 'Khác はずだ (kỳ vọng/suy đoán dựa trên logic chủ quan, có thể sai) — わけだ luôn dựa trên một sự thật/thông tin CÓ THẬT vừa được nêu ra để đi đến kết luận tất yếu.', common_mistake = 'Dùng わけだ khi không có căn cứ, thông tin cụ thể nào phía trước — わけだ bắt buộc phải xuất phát từ một sự việc/lý do đã được nói hoặc ai cũng biết, không phải suy đoán mơ hồ.' where id = '5f22e3d0-6d15-5622-a084-cd95dde9c59f';
update grammar_points set memory_tip = 'わけではない = phủ định "lý do/kết luận" chứ không phủ định toàn bộ sự việc — nhớ là "không hẳn là..., không phải hoàn toàn...".', comparison_note = 'Khác わけがない (phủ định TUYỆT ĐỐI "không thể nào") — わけではない chỉ phủ định MỘT PHẦN, ngầm ý vẫn có khả năng đúng ở mức độ nào đó.', common_mistake = 'Dùng わけではない với nghĩa phủ định hoàn toàn, dứt khoát — mẫu này luôn mang sắc thái mềm mỏng, phủ định một phần, không nên dùng thay cho phủ định tuyệt đối như わけがない.' where id = 'e7e02dc7-2373-5e25-9d44-1243f2a01dd7';
update grammar_points set memory_tip = 'っけ luôn đặt cuối câu, giọng điệu như đang lẩm bẩm tự hỏi lại chính mình — "hình như là... nhỉ?".', comparison_note = 'Khác だろうか (nghi vấn suy đoán về điều CHƯA biết) — っけ dùng khi cố nhớ lại một điều đã biết/đã trải qua nhưng nhất thời quên mất.', common_mistake = 'Dùng っけ trong văn viết hoặc giao tiếp trang trọng — mẫu này chỉ dùng trong khẩu ngữ thân mật, tự nói với bản thân hoặc bạn bè thân thiết.' where id = 'c4463748-e964-5f16-9d62-7540e094f1a0';
update grammar_points set memory_tip = 'とか ở cuối câu nhớ như dấu "..." của lời đồn — thông tin nghe được nhưng người nói không chắc chắn hoàn toàn, chỉ nhắc lại nguyên văn.', comparison_note = 'Khác そうだ (truyền đạt thông tin gián tiếp nhưng chắc chắn, rõ nguồn) — とか mơ hồ hơn, thường dùng khi người nói không nhớ chính xác nguồn tin hoặc muốn giảm nhẹ trách nhiệm về độ chính xác.', common_mistake = 'Dùng とか để khẳng định chắc chắn một thông tin do chính mình chứng kiến — とか chỉ hợp khi thông tin đến từ nguồn thứ hai, thứ ba (nghe kể lại), không dùng cho điều mình tự biết chắc.' where id = 'c8ec66a0-1068-5a52-96db-78a2cb83c363';
update grammar_points set memory_tip = 'どころ vốn nghĩa "nơi chốn/mức" — どころではない nhớ là "còn lâu mới đến mức có thể làm...", nhấn mạnh hoàn cảnh không cho phép.', comparison_note = 'Khác どころか (nghĩa "đừng nói đến A, ngay cả B cũng...") — どころではない chỉ nói về việc KHÔNG THỂ làm gì đó vì bận/khó khăn, không mang tính phủ định leo thang như どころか.', common_mistake = 'Nhầm どころではない với どころか rồi dùng sai cấu trúc — どころではない luôn cần lý do/hoàn cảnh cụ thể khiến không thể làm được việc đó, khác với どころか dùng để phủ định leo thang giữa hai vế.' where id = 'd894b666-2951-51db-8b94-2f53242c081a';
update grammar_points set memory_tip = 'からして nhớ như "ngay từ cái A này đã thấy..." — lấy MỘT ví dụ nhỏ, cụ thể nhất để chứng minh cho một nhận định chung.', comparison_note = 'Khác からすると/からすれば (đứng ở góc độ để đánh giá/suy đoán tổng quát) — からして luôn đưa ra MỘT ví dụ cụ thể, dễ thấy nhất làm bằng chứng minh họa.', common_mistake = 'Dùng からして mà không kèm theo một ví dụ cụ thể, dễ nhận biết — bản chất mẫu này cần một chi tiết nhỏ, rõ ràng (あいさつ、空気、題名) để làm bằng chứng thuyết phục.' where id = '86c19e26-a4d3-5bb3-9203-31c08e38a1af';
update grammar_points set memory_tip = 'からすると／からすれば nhớ như "đứng từ góc độ của..." rồi đưa ra nhận xét hoặc suy đoán.', comparison_note = 'Khác からして (nêu MỘT ví dụ cụ thể làm bằng chứng) — からすると／からすれば đứng trên một LẬP TRƯỜNG/QUAN ĐIỂM tổng quát để nhận xét hoặc suy luận.', common_mistake = 'Dùng からすると để chỉ vị trí bắt đầu về mặt thời gian/không gian (nhầm với から thông thường) — からすると／からすれば chỉ dùng cho việc đánh giá, phán đoán từ một góc nhìn, không phải mốc bắt đầu.' where id = 'e9359294-7fc5-5d5f-bb3c-1be7c173e325';
update grammar_points set memory_tip = 'からには nhớ là "một khi đã..." — hễ điều kiện ở vế trước đã là sự thật thì vế sau là nghĩa vụ/quyết tâm đương nhiên.', comparison_note = 'Gần nghĩa với 以上（は）— からには thiên về ý chí, quyết tâm cá nhân mạnh mẽ hơn, còn 以上は khách quan, trang trọng và có thể dùng trong văn bản quy định.', common_mistake = 'Dùng からには mà vế sau không phải câu thể hiện nghĩa vụ, quyết tâm, suy luận hay mệnh lệnh — cấu trúc này bắt buộc vế sau phải mang một trong các sắc thái đó, không dùng cho câu miêu tả đơn thuần.' where id = '5373979f-3266-57de-8d7e-5e91c88e4b21';
update grammar_points set memory_tip = 'ことだから luôn cần một danh từ chỉ NGƯỜI/ĐỐI TƯỢNG mà cả người nói và người nghe đều đã biết rõ tính cách từ trước.', comparison_note = 'Khác ので (lý do khách quan bất kỳ) — ことだから lý do phải xuất phát từ ĐẶC ĐIỂM, TÍNH CÁCH quen thuộc của một người/sự việc cụ thể mà cả hai bên cùng biết.', common_mistake = 'Dùng ことだから với một đối tượng người nghe hoàn toàn không biết tới — mẫu này chỉ tự nhiên khi cả hai bên hội thoại đều đã có chung hiểu biết về tính cách của người/sự việc đó.' where id = 'e3bf3c4f-df54-5355-8d2e-d40a45643de8';
update grammar_points set memory_tip = 'だけあって／だけに nhớ như "xứng đáng với..." — kết quả ở vế sau luôn TƯƠNG XỨNG (theo hướng tích cực) với nguyên nhân ở vế trước.', comparison_note = 'Đối lập với わりに (kết quả KHÔNG tương xứng, thấp hơn mong đợi so với điều kiện) — だけあって nhấn mạnh sự tương xứng, còn わりに nhấn mạnh sự bất ngờ vì không tương xứng.', common_mistake = 'Dùng だけあって cho kết quả tiêu cực, không tương xứng với nguyên nhân — mẫu này chỉ hợp khi kết quả là điều đáng khen, phù hợp logic với nguyên nhân đã nêu.' where id = 'a67fbf7f-eff3-591d-8f87-3fc1d02d3ebc';
update grammar_points set memory_tip = 'にあたって nhớ như "vào đúng thời điểm quan trọng này..." — chỉ dùng cho những dịp/sự kiện mang tính trang trọng, đặc biệt.', comparison_note = 'Khác に際して (gần nghĩa) — にあたって thường nhấn mạnh thời điểm BẮT ĐẦU một việc quan trọng, còn に際して có thể dùng cả khi đang trong quá trình diễn ra sự việc.', common_mistake = 'Dùng にあたって cho những việc thường ngày, không mang tính trang trọng/đặc biệt — mẫu này chỉ tự nhiên với các sự kiện lớn như khai mạc, phát triển sản phẩm, năm mới.' where id = '407e941f-d553-5cdb-a59c-49c319bfa011';
update grammar_points set memory_tip = 'にかけては luôn đi kèm câu đánh giá TÍCH CỰC ở phía sau — nhớ như "nói riêng về khoản này thì (giỏi/hơn hẳn)...".', comparison_note = 'Khác について (nêu chủ đề trung tính, không hàm ý khen/chê) — にかけては chuyên dùng để khẳng định sự VƯỢT TRỘI, tài năng đặc biệt trong một lĩnh vực cụ thể.', common_mistake = 'Dùng にかけては với câu đánh giá tiêu cực ở sau — theo đúng quy tắc, vế sau にかけては luôn phải là lời khen, đánh giá tích cực về năng lực.' where id = '5e847563-7cc0-52e9-bf72-ac35f6cd709d';
update grammar_points set memory_tip = 'に際して nhớ như "vào dịp/khi đang..." — trang trọng, hay xuất hiện trong bài phát biểu, thư từ.', comparison_note = 'Khác にあたって (gần nghĩa nhưng thiên về thời điểm bắt đầu) — に際して có thể dùng linh hoạt hơn cho cả lúc bắt đầu lẫn trong khi sự việc đang diễn ra.', common_mistake = 'Dùng に際して trong hội thoại đời thường, thân mật — mẫu này mang văn phong trang trọng, hợp với văn viết, phát biểu hơn là nói chuyện hàng ngày.' where id = '101950ca-f9dc-5e0a-af92-d5a60e0501db';
update grammar_points set memory_tip = '先立つ nghĩa đen là "đi trước" — に先立って nhớ như "trước khi (việc lớn) diễn ra, người ta đã làm...".', comparison_note = 'Khác 前に (đơn giản, dùng cho mọi loại "trước khi") — に先立って trang trọng hơn, chuyên dùng cho các sự kiện có quy mô, được chuẩn bị kỹ lưỡng (công chiếu phim, thi tuyển, hội nghị).', common_mistake = 'Dùng に先立って cho việc cá nhân nhỏ nhặt hàng ngày — mẫu này chỉ tự nhiên với sự kiện lớn, mang tính nghi thức hoặc tổ chức.' where id = '4742bf49-01e0-5175-8ff8-301d815080a7';
update grammar_points set memory_tip = 'にしたら／にすれば nhớ như "nếu là..., nếu đứng vào vị trí của... mà nói" — luôn tưởng tượng cảm nhận của MỘT NGƯỜI/ĐỐI TƯỢNG cụ thể.', comparison_note = 'Khác にとって (nêu chuẩn đánh giá chung, khách quan hơn) — にしたら／にすれば thiên về việc tưởng tượng CẢM NHẬN chủ quan, riêng tư của đối tượng đó trong một tình huống cụ thể.', common_mistake = 'Dùng にしたら／にすれば với chủ ngữ là chính người nói (bản thân) — mẫu này chủ yếu dùng để tưởng tượng góc nhìn của NGƯỜI KHÁC, không phải để nói cảm nhận của chính mình.' where id = '96e95e99-7c98-58e3-92c5-623757f945c1';
update grammar_points set memory_tip = 'につき nhớ như phong cách BIỂN THÔNG BÁO — "vì lý do..., (cửa hàng/sự kiện) tạm ngừng/hoãn".', comparison_note = 'Khác ので (lý do thông thường, dùng mọi ngữ cảnh) — につき là cách nói khá cứng, gần như chỉ xuất hiện trong thông báo, biển hiệu, văn bản hành chính.', common_mistake = 'Dùng につき trong hội thoại thân mật hàng ngày — nghe rất kỳ lạ, không tự nhiên; につき gần như chỉ dùng trong văn bản/thông báo chính thức.' where id = 'da9f9d45-7f3a-5776-aad7-9e45bf7f6f6e';
update grammar_points set memory_tip = 'につけ nhớ như "mỗi lần... lại..." — hành động lặp đi lặp lại luôn kéo theo một cảm xúc/suy nghĩ nhất định trỗi dậy.', comparison_note = 'Khác たびに (cũng nghĩa "mỗi lần") — につけ mang văn phong trang trọng, văn học hơn và thường đi kèm cảm xúc ở cuối câu, còn たびに trung tính, dùng phổ biến hơn trong hội thoại.', common_mistake = 'Dùng につけ với động từ chỉ hành động một lần duy nhất, không lặp lại — mẫu này chỉ hợp với hành động có tính LẶP LẠI (xem, nghe nhiều lần) để cảm xúc nảy sinh mỗi lần như vậy.' where id = 'ba392bc6-f0bd-5d28-ad2e-b15b6552af4c';
update grammar_points set memory_tip = 'もと nghĩa gốc là "gốc, nền tảng, dưới chân" — のもとで nhớ như "dưới bóng/dưới sự bảo trợ của...".', comparison_note = 'Khác によって (chỉ phương tiện/tác nhân trực tiếp gây ra sự việc) — のもとで nhấn mạnh MÔI TRƯỜNG, sự chỉ đạo/bảo trợ bao trùm, không phải nguyên nhân trực tiếp.', common_mistake = 'Dùng のもとで để chỉ nguyên nhân trực tiếp của một sự việc (nhầm với によって) — のもとで chỉ hợp khi nói về việc diễn ra DƯỚI sự giám sát, ảnh hưởng, điều kiện của ai/cái gì đó.' where id = 'ed84433f-99f4-5276-a16a-d6dad066f4ae';
update grammar_points set memory_tip = 'ともかく nhớ như "dù sao thì cũng gác lại đã" — はともかく luôn dùng để tạm gác một vấn đề sang bên, tập trung vào vấn đề khác quan trọng hơn.', comparison_note = 'Khác は別として (cũng nghĩa "tạm gác lại", trang trọng hơn) — はともかく thông dụng hơn trong hội thoại hàng ngày, mang sắc thái tự nhiên, ít cứng nhắc hơn.', common_mistake = 'Dùng はともかく để phủ định hoàn toàn vế đầu tiên — thực ra はともかく chỉ tạm thời KHÔNG bàn đến, không có nghĩa là phủ nhận hay bỏ qua vĩnh viễn vế đó.' where id = '1b600119-47d5-5f0d-8bdd-b2ac7818652b';
update grammar_points set memory_tip = 'きっかけ nghĩa là "cơ hội, cái cớ tình cờ" — をきっかけに nhớ như "nhân dịp (tình cờ) đó mà...".', comparison_note = 'Gần nghĩa を契機に nhưng をきっかけに thông dụng hơn, dùng được cho cả sự kiện nhỏ nhặt, tình cờ trong đời sống hàng ngày, không nhất thiết phải là bước ngoặt lớn.', common_mistake = 'Dùng をきっかけに cho một quá trình lâu dài, có chủ đích rõ ràng ngay từ đầu — mẫu này hợp hơn với những sự việc mang tính TÌNH CỜ, ngẫu nhiên làm khởi nguồn cho một thay đổi.' where id = 'ae305f71-3dbf-58bf-8ca6-0e11a816b5e7';
update grammar_points set memory_tip = '契機（けいき）nghĩa Hán Việt là "khế cơ, cơ hội, bước ngoặt" — を契機に mang tính trang trọng, quy mô lớn hơn をきっかけに.', comparison_note = 'Gần nghĩa をきっかけに nhưng を契機に thường dùng cho các sự kiện lớn, có tính lịch sử/xã hội (khủng hoảng dầu mỏ, duy tân Meiji), ít dùng cho chuyện cá nhân vụn vặt.', common_mistake = 'Dùng を契機に cho chuyện cá nhân nhỏ nhặt đời thường — mẫu này nghe trang trọng, quy mô lớn nên tự nhiên hơn khi nói về sự kiện xã hội/công việc quan trọng, thay vì chuyện vặt cá nhân.' where id = '454ba874-b67b-5748-a136-62b0e7eef704';
update grammar_points set memory_tip = 'を～として nhớ theo công thức "lấy A làm B" — A đứng trước を, B đứng trước として, xác định vai trò/mục đích/tiêu chuẩn.', comparison_note = 'Khác にとって (nêu góc nhìn đánh giá) — を～として xác định một vai trò/danh nghĩa CỤ THỂ mà đối tượng A được gán cho, không phải góc nhìn đánh giá của ai.', common_mistake = 'Đảo ngược vị trí trước/sau của を và として khiến câu tối nghĩa — cần nhớ đúng thứ tự [A]を[B]として, nghĩa là lấy A làm B, không phải ngược lại.' where id = 'e1ce5d7d-ca68-5f88-90d1-45fb8711be9f';
update grammar_points set memory_tip = 'あげく nhớ như "rốt cuộc, cuối cùng thì..." — luôn theo sau một quá trình dài đắn đo/cố gắng và thường kết thúc KHÔNG NHƯ Ý.', comparison_note = 'Khác た末に (cùng batch, gần nghĩa) — あげく thường mang kết quả tiêu cực, đáng tiếc; còn 末に trung tính hơn, có thể dùng cho cả kết quả tích cực.', common_mistake = 'Dùng あげく cho một kết quả tích cực, đáng mừng — về nguyên tắc あげく hầu như luôn đi kèm kết quả xấu, không như ý hoặc gây hối tiếc.' where id = 'eaa03502-8b37-57df-a862-755d8293bb6b';
update grammar_points set memory_tip = '以上（は）nhớ như "đã ở tình huống/mức độ này rồi thì..." — mang tính khách quan, trang trọng, hay dùng trong văn bản quy định.', comparison_note = 'Gần nghĩa からには nhưng 以上は khách quan, ít cảm xúc cá nhân hơn, phù hợp cả trong văn viết chính thức, quy tắc, luật lệ.', common_mistake = 'Dùng ［名－の］+以上 (thêm の) — mẫu này với danh từ phải dùng である chứ không phải の, ví dụ 親子である以上 chứ không phải 親子の以上.' where id = '50f67271-14e8-5fbd-9dbe-87e9273a6c52';
update grammar_points set memory_tip = '上は nhớ như phiên bản trang trọng, ít dùng hơn của からには／以上は — chỉ nối sau động từ (từ điển hoặc た形).', comparison_note = 'Gần nghĩa 以上は và からには nhưng 上は là cách nói cứng, trang trọng nhất trong ba mẫu, ít xuất hiện trong hội thoại đời thường.', common_mistake = 'Dùng 上は sau danh từ hoặc tính từ — mẫu này chỉ nối được sau động từ (辞書形/た形), khác với 以上 có thể đi sau cả danh từ, tính từ.' where id = '7c0e4d39-7a24-50a6-84c4-7188abda0b4c';
update grammar_points set memory_tip = 'ことなく nhớ như phiên bản trang trọng, văn viết của ～ないで — luôn nối sau động từ thể từ điển.', comparison_note = 'Khác ないで (thông dụng, dùng cả văn nói lẫn văn viết) — ことなく mang văn phong trang trọng, formal, hay gặp trong văn viết, bài phát biểu, tin tức.', common_mistake = 'Dùng ことなく trong hội thoại thân mật hàng ngày thay vì ないで — nghe khá cứng nhắc, không tự nhiên trong giao tiếp thông thường.' where id = '067c170e-f9d0-5751-877c-2255b4b26fe3';
update grammar_points set memory_tip = '際（さい）nhớ như phiên bản trang trọng của とき — thường xuất hiện trong hướng dẫn, biểu mẫu, thông báo chính thức.', comparison_note = 'Khác とき (thông dụng, trung tính, dùng mọi ngữ cảnh) — 際 mang tính trang trọng hơn, hay dùng trong văn bản hướng dẫn, quy định, thủ tục hành chính.', common_mistake = 'Dùng 際 trong hội thoại suồng sã hàng ngày thay vì とき — tuy không sai ngữ pháp nhưng nghe khá cứng nhắc, kém tự nhiên so với ngữ cảnh thân mật.' where id = 'a37a2314-3d3c-5d43-8d82-e29c4f5a96ec';
